def get_diffs(block):
    a, b, c = block
    return [(a-b)%13, (b-a)%13, (a-c)%13, (c-a)%13, (b-c)%13, (c-b)%13]

blocks = [(0, 1, 3), (1, 3, 11), (2, 3, 10), (2, 6, 8), (3, 9, 11), (2, 6, 9), (6, 10, 11), (0, 1, 4)]
diff_counts = [0] * 13
for b in blocks:
    for d in get_diffs(b):
        diff_counts[d] += 1
print(diff_counts)
# Expected: [0, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4, 4]

# We have 8 base blocks: (0, 1, 3), (1, 3, 11), (2, 3, 10), (2, 6, 8), (3, 9, 11), (2, 6, 9), (6, 10, 11), (0, 1, 4)
# Each base block generates 13 blocks by adding i mod 13 for i in 0..12.
# Total 8 * 13 = 104 blocks.
# Let's construct the 13x104 matrix.

base_blocks = [(0, 1, 3), (1, 3, 11), (2, 3, 10), (2, 6, 8), (3, 9, 11), (2, 6, 9), (6, 10, 11), (0, 1, 4)]
all_blocks = []
for b in base_blocks:
    for i in range(13):
        all_blocks.append(((b[0]+i)%13, (b[1]+i)%13, (b[2]+i)%13))

# Matrix is 13 rows, 104 columns.
# x[row][col] = 1 if row is in all_blocks[col], else 0.
matrix = [[0 for _ in range(104)] for _ in range(13)]
for col_idx, block in enumerate(all_blocks):
    for row_idx in block:
        matrix[row_idx][col_idx] = 1

# Verify:
# 1. Row sums:
for r in range(13):
    if sum(matrix[r]) != 24:
        print(f"Row {r} sum is {sum(matrix[r])}")

# 2. Column sums:
for c in range(104):
    if sum(matrix[r][c] for r in range(13)) != 3:
        print(f"Col {c} sum is {sum(matrix[r][c] for r in range(13))}")

# 3. Inner product of rows:
for i in range(13):
    for j in range(i + 1, 13):
        inner_prod = sum(matrix[i][k] * matrix[j][k] for k in range(104))
        if inner_prod != 4:
            print(f"Inner product of row {i} and {j} is {inner_prod}")

# Flatten the matrix
flat_matrix = [val for row in matrix for val in row]
print(len(flat_matrix))
